import numpy as np
f=np.load('source_pixels.npz')['rgb']
# Determine object shape / mask by comparing frame0 and frame48. frame0 has red initial at 135..146,64..71; frame48 final 107..120,73..82.
# print crops side by side as tiled RGB with red/blue boundaries
from PIL import Image,ImageDraw
for i,box in [(0,(125,55,155,82)),(48,(98,67,130,92)),(0,(155,50,177,72)),(16,(135,56,158,75))]:
 im=Image.fromarray(f[i]).crop(box).resize(((box[2]-box[0])*20,(box[3]-box[1])*20),Image.Resampling.NEAREST)
 d=ImageDraw.Draw(im)
 for x in range(box[0],box[2]):
  if x%2==0:d.line(((x-box[0])*20,0,(x-box[0])*20,im.height),fill=(255,0,255))
 for y in range(box[1],box[3]):
  if y%2==0:d.line((0,(y-box[1])*20,im.width,(y-box[1])*20),fill=(255,0,255))
 im.save(f'.tmp/obj_{i}_{box[0]}_{box[1]}.png')
PY"

