import numpy as np
from PIL import Image, ImageDraw
f=np.load('source_pixels.npz')['rgb']
for name,i,cx,cy in [('red',0,141,68),('blue',0,167,59)]:
 x0,y0=cx-15,cy-13; x1,y1=cx+15,cy+13
 im=Image.fromarray(f[i]).crop((x0,y0,x1,y1)).resize(((x1-x0)*30,(y1-y0)*30),Image.Resampling.NEAREST)
