 for x in range(x0,x1):
  d.line(((x-x0)*30,0,(x-x0)*30,im.height),fill=(255,0,255),width=1)
  if x%2==0:d.text(((x-x0)*30+1,1),str(x),fill=(255,255,0))
 for y in range(y0,y1):
  d.line((0,(y-y0)*30,im.width,(y-y0)*30),fill=(255,0,255),width=1)
  if y%2==0:d.text((1,(y-y0)*30+1),str(y),fill=(255,255,0))
 im.save(f'.tmp/{name}_sprite_grid.png')
